const now = new Date().toISOString();
const caseId = `SCAM-${Date.now()}`;
const narrative = 'A WhatsApp account offered a work-from-home job and asked me to pay a registration fee before starting.';
return [{ json: {
  case_state: { case_id: caseId, state_version: 0, sources: [], evidence: [], indicators: [], analysis: null, missing_information: [], research_count: 0, revision_count: 0, agent_history: [], created_at: now, updated_at: now },
  user_submission: { narrative, country: 'IN', evidence: [{ name: 'Example WhatsApp message', text: 'Pay a registration fee today to unlock your work assignment.' }] },
  incoming_message: { case_id: caseId, sender: 'user_intake', recipient: 'scam_analysis_agent', message_type: 'USER_SUBMISSION', objective: 'Structure this user report and decide whether it is ready for verification.', evidence_refs: [], findings: [], confidence: 0, rationale: 'Safe Phase 1 demonstration input.', missing_information: [], requested_action: 'ANALYSE_USER_REPORT', recommended_action: 'SEND_TO_ANALYSIS', status: 'IN_PROGRESS', timestamp: now }
} }];

const beforeAnalysis = $('Initialise Safe Demonstration Case').first().json.case_state;
const result = $input.first().json;
const patch = result.case_patch ?? {};
const state = { ...beforeAnalysis, ...patch, state_version: (beforeAnalysis.state_version ?? 0) + 1, updated_at: new Date().toISOString() };
return [{ json: { case_state: state, analysis_message: result.message } }];

const current = $input.first().json;
const message = current.analysis_message;
const routes = { SEND_TO_VERIFICATION: 'PHASE_2_VERIFICATION', REQUEST_MORE_USER_EVIDENCE: 'REQUEST_USER_EVIDENCE', ESCALATE: 'HELD_FOR_REVIEW' };
return [{ json: { ...current, next_stage: routes[message.recommended_action] ?? 'HELD_FOR_REVIEW', final_message: message, note: 'This controller does not invoke Scam Search. Phase 2 Verification decides whether to request Search.' } }];
